-- Additive Student identity, admission, guardian, exit history and authority-ID schema.
-- Apply only after a recoverable database backup; do not seed personal/student data.
-- Uses current shared Institution, Country, Gender, Campus and academic master keys.

BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."Student" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentCode" varchar(80) NOT NULL,
    "AdmissionNumber" varchar(80),
    "FirstName" varchar(100) NOT NULL,
    "MiddleName" varchar(100),
    "LastName" varchar(100) NOT NULL,
    "DateOfBirth" date NOT NULL,
    "GenderId" integer NOT NULL,
    "CountryId" integer NOT NULL,
    "LifecycleStatus" smallint NOT NULL DEFAULT 1,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    CONSTRAINT "FK_Student_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Student_Country" FOREIGN KEY ("CountryId") REFERENCES skolenza."Country"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Student_Gender" FOREIGN KEY ("GenderId") REFERENCES skolenza."Gender"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Student_LifecycleStatus" CHECK ("LifecycleStatus" IN (1, 2))
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Student_Institution_StudentCode" ON skolenza."Student" ("InstitutionId", "StudentCode");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Student_Institution_AdmissionNumber" ON skolenza."Student" ("InstitutionId", "AdmissionNumber")
    WHERE "AdmissionNumber" IS NOT NULL AND NOT "IsSoftDeleted";

CREATE TABLE IF NOT EXISTS skolenza."StudentAdmission" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "ApplicationNumber" varchar(80) NOT NULL,
    "AcademicSessionId" bigint NOT NULL,
    "CampusId" bigint NOT NULL,
    "AcademicGroupId" bigint NOT NULL,
    "FirstName" varchar(100) NOT NULL,
    "MiddleName" varchar(100),
    "LastName" varchar(100) NOT NULL,
    "DateOfBirth" date NOT NULL,
    "GenderId" integer NOT NULL,
    "CountryId" integer NOT NULL,
    "Status" smallint NOT NULL DEFAULT 1,
    "ReviewReason" varchar(1000),
    "StudentId" bigint,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    CONSTRAINT "FK_StudentAdmission_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmission_AcademicSession" FOREIGN KEY ("AcademicSessionId") REFERENCES skolenza."AcademicSessionMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmission_Campus" FOREIGN KEY ("CampusId") REFERENCES skolenza."Campus"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmission_AcademicGroup" FOREIGN KEY ("AcademicGroupId") REFERENCES skolenza."AcademicGroupMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmission_Gender" FOREIGN KEY ("GenderId") REFERENCES skolenza."Gender"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmission_Country" FOREIGN KEY ("CountryId") REFERENCES skolenza."Country"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmission_Student" FOREIGN KEY ("StudentId") REFERENCES skolenza."Student"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentAdmission_Status" CHECK ("Status" BETWEEN 1 AND 7)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentAdmission_Institution_ApplicationNumber" ON skolenza."StudentAdmission" ("InstitutionId", "ApplicationNumber");
CREATE INDEX IF NOT EXISTS "IX_StudentAdmission_Institution_Status" ON skolenza."StudentAdmission" ("InstitutionId", "Status", "AddedDateTime" DESC);

CREATE TABLE IF NOT EXISTS skolenza."StudentAdmissionStatusHistory" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionId" bigint NOT NULL,
    "FromStatus" smallint NOT NULL,
    "ToStatus" smallint NOT NULL,
    "Reason" varchar(1000),
    "ChangedById" bigint NOT NULL,
    "ChangedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentAdmissionStatusHistory_Admission" FOREIGN KEY ("StudentAdmissionId") REFERENCES skolenza."StudentAdmission"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentAdmissionStatusHistory_ToStatus" CHECK ("ToStatus" BETWEEN 1 AND 7)
);
CREATE INDEX IF NOT EXISTS "IX_StudentAdmissionStatusHistory_Admission" ON skolenza."StudentAdmissionStatusHistory" ("InstitutionId", "StudentAdmissionId", "ChangedDateTime");

CREATE TABLE IF NOT EXISTS skolenza."StudentEnrollment" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentId" bigint NOT NULL,
    "AcademicSessionId" bigint NOT NULL,
    "CampusId" bigint NOT NULL,
    "AcademicGroupId" bigint NOT NULL,
    "AcademicProgrammeId" bigint,
    "RollNumber" varchar(80),
    "Status" smallint NOT NULL DEFAULT 2,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date,
    "IsActive" boolean NOT NULL DEFAULT true,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    CONSTRAINT "FK_StudentEnrollment_Student" FOREIGN KEY ("StudentId") REFERENCES skolenza."Student"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentEnrollment_AcademicSession" FOREIGN KEY ("AcademicSessionId") REFERENCES skolenza."AcademicSessionMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentEnrollment_Campus" FOREIGN KEY ("CampusId") REFERENCES skolenza."Campus"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentEnrollment_AcademicGroup" FOREIGN KEY ("AcademicGroupId") REFERENCES skolenza."AcademicGroupMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentEnrollment_AcademicProgramme" FOREIGN KEY ("AcademicProgrammeId") REFERENCES skolenza."AcademicProgrammeMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentEnrollment_Status" CHECK ("Status" BETWEEN 1 AND 6),
    CONSTRAINT "CK_StudentEnrollment_EffectiveDates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom")
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentEnrollment_Student_Session" ON skolenza."StudentEnrollment" ("InstitutionId", "StudentId", "AcademicSessionId");
CREATE INDEX IF NOT EXISTS "IX_StudentEnrollment_Institution_Session_Group" ON skolenza."StudentEnrollment" ("InstitutionId", "AcademicSessionId", "AcademicGroupId", "CampusId");

CREATE TABLE IF NOT EXISTS skolenza."Guardian" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "FirstName" varchar(100) NOT NULL,
    "MiddleName" varchar(100),
    "LastName" varchar(100) NOT NULL,
    "Email" varchar(254),
    "PhoneNumber" varchar(30),
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    CONSTRAINT "FK_Guardian_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Guardian_Institution_Email" ON skolenza."Guardian" ("InstitutionId", "Email") WHERE "Email" IS NOT NULL AND NOT "IsSoftDeleted";

CREATE TABLE IF NOT EXISTS skolenza."StudentGuardian" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentId" bigint NOT NULL,
    "GuardianId" bigint NOT NULL,
    "RelationshipType" smallint NOT NULL,
    "IsPrimary" boolean NOT NULL DEFAULT false,
    "IsEmergencyContact" boolean NOT NULL DEFAULT false,
    "IsPickupAuthorized" boolean NOT NULL DEFAULT false,
    "HasPortalAccess" boolean NOT NULL DEFAULT true,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date,
    "IsActive" boolean NOT NULL DEFAULT true,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentGuardian_Student" FOREIGN KEY ("StudentId") REFERENCES skolenza."Student"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentGuardian_Guardian" FOREIGN KEY ("GuardianId") REFERENCES skolenza."Guardian"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentGuardian_RelationshipType" CHECK ("RelationshipType" BETWEEN 1 AND 5),
    CONSTRAINT "CK_StudentGuardian_EffectiveDates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom")
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentGuardian_ActiveLink" ON skolenza."StudentGuardian" ("InstitutionId", "StudentId", "GuardianId") WHERE "IsActive";
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentGuardian_OnePrimary" ON skolenza."StudentGuardian" ("InstitutionId", "StudentId") WHERE "IsActive" AND "IsPrimary";

CREATE TABLE IF NOT EXISTS skolenza."StudentAdmissionGuardian" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionId" bigint NOT NULL,
    "GuardianId" bigint NOT NULL,
    "RelationshipType" smallint NOT NULL,
    "IsPrimary" boolean NOT NULL DEFAULT false,
    "IsEmergencyContact" boolean NOT NULL DEFAULT false,
    "IsPickupAuthorized" boolean NOT NULL DEFAULT false,
    "HasPortalAccess" boolean NOT NULL DEFAULT true,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date,
    "IsActive" boolean NOT NULL DEFAULT true,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    CONSTRAINT "FK_StudentAdmissionGuardian_Admission" FOREIGN KEY ("StudentAdmissionId") REFERENCES skolenza."StudentAdmission"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmissionGuardian_Guardian" FOREIGN KEY ("GuardianId") REFERENCES skolenza."Guardian"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentAdmissionGuardian_RelationshipType" CHECK ("RelationshipType" BETWEEN 1 AND 5),
    CONSTRAINT "CK_StudentAdmissionGuardian_EffectiveDates" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom")
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentAdmissionGuardian_ActiveLink" ON skolenza."StudentAdmissionGuardian" ("InstitutionId", "StudentAdmissionId", "GuardianId") WHERE "IsActive";
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentAdmissionGuardian_OnePrimary" ON skolenza."StudentAdmissionGuardian" ("InstitutionId", "StudentAdmissionId") WHERE "IsActive" AND "IsPrimary";

CREATE TABLE IF NOT EXISTS skolenza."StudentExitHistory" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentId" bigint NOT NULL,
    "StudentEnrollmentId" bigint,
    "PreviousSchoolName" varchar(250),
    "PreviousSchoolCountryId" integer,
    "DestinationSchoolName" varchar(250),
    "DestinationSchoolCountryId" integer,
    "EffectiveExitDate" date NOT NULL,
    "ExitReason" smallint NOT NULL,
    "Notes" varchar(2000),
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentExitHistory_Student" FOREIGN KEY ("StudentId") REFERENCES skolenza."Student"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentExitHistory_StudentEnrollment" FOREIGN KEY ("StudentEnrollmentId") REFERENCES skolenza."StudentEnrollment"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentExitHistory_PreviousCountry" FOREIGN KEY ("PreviousSchoolCountryId") REFERENCES skolenza."Country"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentExitHistory_DestinationCountry" FOREIGN KEY ("DestinationSchoolCountryId") REFERENCES skolenza."Country"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentExitHistory_Reason" CHECK ("ExitReason" BETWEEN 1 AND 4)
);
CREATE INDEX IF NOT EXISTS "IX_StudentExitHistory_Institution_Student" ON skolenza."StudentExitHistory" ("InstitutionId", "StudentId", "EffectiveExitDate" DESC);

CREATE TABLE IF NOT EXISTS skolenza."StudentEducationIdentifierMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "TemplateSourceId" bigint,
    "CountryId" integer NOT NULL,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "IssuingAuthority" varchar(150) NOT NULL,
    "Description" varchar(500),
    "DisplayOrder" smallint NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSystemDefined" boolean NOT NULL DEFAULT false,
    "AddedById" bigint,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "SoftDeletedById" bigint,
    "DeletedDateTime" timestamp,
    CONSTRAINT "FK_StudentEducationIdentifierMaster_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentEducationIdentifierMaster_Country" FOREIGN KEY ("CountryId") REFERENCES skolenza."Country"("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentEducationIdentifierMaster_Institution_Country_Code" ON skolenza."StudentEducationIdentifierMaster" ("InstitutionId", "CountryId", upper("Code")) WHERE NOT "IsSoftDeleted";

CREATE TABLE IF NOT EXISTS skolenza."StudentEducationIdentifier" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentId" bigint NOT NULL,
    "IdentifierMasterId" bigint NOT NULL,
    "CountryId" integer NOT NULL,
    "EncryptedValue" varchar(2000) NOT NULL,
    "MaskedValue" varchar(80) NOT NULL,
    "VerificationStatus" smallint NOT NULL DEFAULT 1,
    "IssuerReference" varchar(150),
    "IssuedOn" date,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "VerifiedById" bigint,
    "VerifiedDateTime" timestamp,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    CONSTRAINT "FK_StudentEducationIdentifier_Student" FOREIGN KEY ("StudentId") REFERENCES skolenza."Student"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentEducationIdentifier_Master" FOREIGN KEY ("IdentifierMasterId") REFERENCES skolenza."StudentEducationIdentifierMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentEducationIdentifier_Country" FOREIGN KEY ("CountryId") REFERENCES skolenza."Country"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentEducationIdentifier_VerificationStatus" CHECK ("VerificationStatus" BETWEEN 1 AND 3)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentEducationIdentifier_Student_Master" ON skolenza."StudentEducationIdentifier" ("InstitutionId", "StudentId", "IdentifierMasterId");

CREATE TABLE IF NOT EXISTS skolenza."StudentEducationIdentifierVerificationHistory" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentEducationIdentifierId" bigint NOT NULL,
    "FromStatus" smallint NOT NULL,
    "ToStatus" smallint NOT NULL,
    "Reason" varchar(500),
    "ChangedById" bigint NOT NULL,
    "ChangedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentEducationIdentifierVerificationHistory_Identifier"
        FOREIGN KEY ("StudentEducationIdentifierId")
        REFERENCES skolenza."StudentEducationIdentifier"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentEducationIdentifierVerificationHistory_Status"
        CHECK ("FromStatus" BETWEEN 1 AND 3 AND "ToStatus" BETWEEN 1 AND 3)
);
CREATE INDEX IF NOT EXISTS "IX_StudentEducationIdentifierVerificationHistory_Identifier_Date"
    ON skolenza."StudentEducationIdentifierVerificationHistory"
       ("InstitutionId", "StudentEducationIdentifierId", "ChangedDateTime" DESC);

CREATE TABLE IF NOT EXISTS skolenza."StudentAdmissionDocument" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionId" bigint NOT NULL,
    "RequirementId" bigint NOT NULL,
    "GuardianId" bigint,
    "PersonScope" smallint NOT NULL,
    "VersionNumber" integer NOT NULL,
    "SupersedesDocumentId" bigint,
    "OriginalFileName" varchar(255) NOT NULL,
    "StorageProvider" varchar(30) NOT NULL DEFAULT 'S3',
    "ObjectKey" varchar(1000) NOT NULL,
    "ContentType" varchar(150) NOT NULL,
    "FileSizeBytes" bigint NOT NULL,
    "ChecksumSha256" varchar(64) NOT NULL,
    "ExpiryDate" date,
    "Status" smallint NOT NULL DEFAULT 1,
    "SubmittedById" bigint NOT NULL,
    "SubmittedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ReviewedById" bigint,
    "ReviewedDateTime" timestamp,
    "ReviewReason" varchar(1000),
    CONSTRAINT "FK_StudentAdmissionDocument_Admission" FOREIGN KEY ("StudentAdmissionId") REFERENCES skolenza."StudentAdmission"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmissionDocument_Requirement" FOREIGN KEY ("RequirementId") REFERENCES skolenza."StudentDocumentRequirementMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmissionDocument_Guardian" FOREIGN KEY ("GuardianId") REFERENCES skolenza."Guardian"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentAdmissionDocument_Supersedes" FOREIGN KEY ("SupersedesDocumentId") REFERENCES skolenza."StudentAdmissionDocument"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentAdmissionDocument_PersonScope" CHECK ("PersonScope" BETWEEN 1 AND 3),
    CONSTRAINT "CK_StudentAdmissionDocument_GuardianScope" CHECK (("PersonScope" = 1 AND "GuardianId" IS NULL) OR ("PersonScope" IN (2, 3) AND "GuardianId" IS NOT NULL)),
    CONSTRAINT "CK_StudentAdmissionDocument_Version" CHECK ("VersionNumber" > 0),
    CONSTRAINT "CK_StudentAdmissionDocument_Size" CHECK ("FileSizeBytes" > 0),
    CONSTRAINT "CK_StudentAdmissionDocument_Status" CHECK ("Status" BETWEEN 1 AND 4)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentAdmissionDocument_Version" ON skolenza."StudentAdmissionDocument" ("InstitutionId", "StudentAdmissionId", "RequirementId", "PersonScope", "GuardianId", "VersionNumber");
CREATE INDEX IF NOT EXISTS "IX_StudentAdmissionDocument_Admission_Status" ON skolenza."StudentAdmissionDocument" ("InstitutionId", "StudentAdmissionId", "Status", "Id");

CREATE TABLE IF NOT EXISTS skolenza."StudentAdmissionDocumentReviewHistory" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionDocumentId" bigint NOT NULL,
    "FromStatus" smallint NOT NULL,
    "ToStatus" smallint NOT NULL,
    "Reason" varchar(1000),
    "ChangedById" bigint NOT NULL,
    "ChangedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentAdmissionDocumentReviewHistory_Document" FOREIGN KEY ("StudentAdmissionDocumentId") REFERENCES skolenza."StudentAdmissionDocument"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentAdmissionDocumentReviewHistory_Status" CHECK ("FromStatus" BETWEEN 0 AND 4 AND "ToStatus" BETWEEN 1 AND 4)
);
CREATE INDEX IF NOT EXISTS "IX_StudentAdmissionDocumentReviewHistory_Document" ON skolenza."StudentAdmissionDocumentReviewHistory" ("InstitutionId", "StudentAdmissionDocumentId", "ChangedDateTime");

COMMIT;
